using UnityEngine;

// Карты уровней. Один символ — одна клетка 16x16 пикселей.
//
// Верхняя строка массива — верх экрана, нижняя — низ. Ширина всех строк
// одного уровня обязана совпадать: LevelBuilder ругается в консоль, если нет.
//
// Что означают символы:
//
//   .  пусто                     #  земля
//   =  твёрдый блок              B  кирпич (большой герой разбивает)
//   ?  блок с монетой            M  блок с усилителем
//   U  блок с жизнью             o  монета
//   g  враг «грибыш»             k  враг «панцирь»
//   [ ]  верх трубы              { }  тело трубы
//   S  старт героя               F  флаг (шест достраивается сам)
//   c  облако (фон)              h  холм (фон)          v  куст (фон)
//
// Правка уровня — правка вот этих строк, больше ничего трогать не надо.
// Главное: не менять длину строк по отдельности, иначе поплывёт карта.
public static class LevelData
{
    public static string[][] Vse = { Uroven1, Uroven2, Uroven3 };

    public static string[] Poluchit(int nomer)
    {
        return Vse[Mathf.Clamp(nomer - 1, 0, Vse.Length - 1)];
    }

